command:
$ErrorActionPreference="Stop"
$svc=Get-Service WSearch -ErrorAction SilentlyContinue
if($svc){Write-Host ("INDEX_SERVICE_STATUS="+$svc.Status)}else{Write-Host "INDEX_SERVICE_STATUS=MISSING"}
$script = @'
$ErrorActionPreference="Stop"
try {
 $conn=New-Object System.Data.OleDb.OleDbConnection("Provider=Search.CollatorDSO.1;Extended Properties=`"Application=Windows`"")
 $conn.Open()
 $cmd=$conn.CreateCommand()
 $cmd.CommandText="SELECT TOP 5 System.ItemUrl FROM SystemIndex"
 $r=$cmd.ExecuteReader()
 $n=0;while($r.Read()){ $n++;Write-Output ("INDEX_SAMPLE_URL="+[string]$r.GetValue(0)) }
 $r.Close();$conn.Close();Write-Output ("INDEX_QUERY=PASS SAMPLES="+$n)
} catch {Write-Output ("INDEX_QUERY=FAIL "+$_.Exception.GetType().Name+" "+$_.Exception.Message)}
'@
$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($script))
& powershell.exe -NoProfile -NonInteractive -EncodedCommand $encoded
if($LASTEXITCODE -ne 0){throw "Windows PowerShell diagnostic failed"}
Write-Host "INDEX_READINESS_DIAG=PASS"
